namespace emon;


public static class Oapptest {
    [Xunit.Fact]
    public static void TestPpArithmeticRequiresASourceRuleAboveItsTotal() {
        emon.Port.Cells rules = emon.Port.NewCells();
        emon.Port.Cells words = emon.Port.NewCells();
        int w = Evidence.OwNew(words, 1, 1000, 2000, 1500, 2200, 0, 0, 0, 0, 0, 0, 0, 3, 0, 900, -1);
        emon.Testport.AssertEq(Oapp.PpTotalRule(rules, words, 1, w), 0, "prose has no total rule");
        int otherPage = Evidence.RlNew(rules, 2, 900, 1900, 1600, 1950, 0);
        Evidence.RlSet(rules, otherPage, Evidence.RlfConf(), 1000);
        emon.Testport.AssertEq(Oapp.PpTotalRule(rules, words, 1, w), 0, "another page supplies no rule");
        int shortRule = Evidence.RlNew(rules, 1, 1100, 1900, 1400, 1950, 0);
        Evidence.RlSet(rules, shortRule, Evidence.RlfConf(), 1000);
        emon.Testport.AssertEq(Oapp.PpTotalRule(rules, words, 1, w), 0, "a short stroke does not span the total");
        int totalRule = Evidence.RlNew(rules, 1, 900, 1900, 1600, 1950, 0);
        Evidence.RlSet(rules, totalRule, Evidence.RlfConf(), 1000);
        emon.Testport.AssertEq(Oapp.PpTotalRule(rules, words, 1, w), 1, "source rule spans the total");
    }
}
